/**
 * Environment Configuration — Validates and exports all environment variables.
 * Uses Joi for schema validation to catch config errors at startup.
 * Generated by BackendForge
 */

const Joi = require('joi');
const dotenv = require('dotenv');
const path = require('path');

// Load .env file
dotenv.config({ path: path.resolve(process.cwd(), '.env') });

const envSchema = Joi.object({
  // Server
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),
  PORT: Joi.number().default(3000),
  API_PREFIX: Joi.string().default('/api'),
  FRONTEND_URL: Joi.string().uri().default('http://localhost:5173'),

  // Database
  DATABASE_URL: Joi.string().required().description('Database connection URL'),
  DB_POOL_MAX: Joi.number().default(10),
  DB_POOL_MIN: Joi.number().default(2),
  DB_POOL_IDLE: Joi.number().default(10000),

  // Redis
  REDIS_URL: Joi.string().default('redis://localhost:6379'),

  // Auth
  JWT_SECRET: Joi.string().min(32).required().description('JWT signing secret — must be strong!'),
  JWT_EXPIRY: Joi.string().default('24h'),
  JWT_REFRESH_EXPIRY: Joi.string().default('7d'),
  BCRYPT_ROUNDS: Joi.number().default(12),

  // Payment
  STRIPE_SECRET_KEY: Joi.string().required(),
  STRIPE_PUBLISHABLE_KEY: Joi.string().required(),
  STRIPE_WEBHOOK_SECRET: Joi.string().required(),

  // OTP
  TWILIO_ACCOUNT_SID: Joi.string().required(),
  TWILIO_AUTH_TOKEN: Joi.string().required(),
  TWILIO_PHONE_NUMBER: Joi.string().required(),

  // Email
  SMTP_HOST: Joi.string().default('smtp.gmail.com'),
  SMTP_PORT: Joi.number().default(587),
  SMTP_USER: Joi.string().email().allow(''),
  SMTP_PASS: Joi.string().allow(''),
  EMAIL_FROM: Joi.string().default('noreply@example.com'),

  // Security
  RATE_LIMIT_WINDOW_MS: Joi.number().default(900000),
  RATE_LIMIT_MAX_REQUESTS: Joi.number().default(100),
  ADMIN_RATE_LIMIT_MAX: Joi.number().default(20),
  OTP_EXPIRY_MINUTES: Joi.number().default(5),
  ORDER_CANCEL_WINDOW_HOURS: Joi.number().default(2),

  // Logging
  LOG_LEVEL: Joi.string().valid('error', 'warn', 'info', 'debug').default('debug'),
  LOG_FILE: Joi.string().default('logs/app.log'),

  // CORS
  CORS_ORIGINS: Joi.string().default('http://localhost:3000,http://localhost:5173'),
}).unknown(true); // Allow extra env vars

const { value: env, error } = envSchema.validate(process.env, {
  abortEarly: false,
  stripUnknown: false,
});

if (error) {
  const messages = error.details.map(d => `  • ${d.message}`).join('\n');
  console.error(`\n❌ Environment validation failed:\n${messages}\n`);
  console.error('💡 Copy .env.example to .env and fill in your values:\n   cp .env.example .env\n');
  process.exit(1);
}

module.exports = { env };
